import {conversionNeedsApproval} from './planning-data.js';
import {capturePanorama,sphericalViewer} from './panorama.js';
import {roomStation,sceneFingerprint} from './interior-data.js';
import {floorRecord,planning,layoutKey,fingerprint} from './planning-data.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
export function mountFreeModelStudio(b){let models=[],jobs=[],busy=false,visible=false,dispose=null,error='';const button=document.createElement('button');button.id='free-models-btn';button.className='rail-btn';button.innerHTML='<svg><use href="#i-spark"/></svg><span>AI models</span>';$('.rail').append(button);$('#modal').addEventListener('close',()=>{visible=false;dispose?.();dispose=null;});button.onclick=()=>open();
 async function api(url,options={}){const r=await fetch(url,{...options,headers:{'Content-Type':'application/json','X-Hestia-Client':'studio'}}),data=await r.json();if(!r.ok)throw Error(data.error||'Model service unavailable.');return data;}
 async function open(){visible=true;dispose?.();dispose=null;error='';try{models=(await api('/api/ai/free-models')).models;const p=b.getProject();jobs=(await api('/api/ai/jobs?projectId='+encodeURIComponent(p.id))).jobs.filter(j=>j.provider==='imagerouter');}catch(e){error=e.message;}render();}
 function render(){const f=b.getFloor();b.modal(`<div class="plan-lab"><span class="eyebrow">CURATED · FREE · REVIEWED BY YOU</span><h2>Quality before Auto Free</h2><p>Only two image-editing candidates are considered. Availability and all advertised price bounds must be verified as zero. Each model needs a real completed image and your quality review for each task before Auto Free can select it. These are your acceptance checks, not independent benchmark scores.</p><p>ImageRouter receives model captures when you explicitly generate. Only this enabled service is used by Auto Free; it will not switch to Cloudflare, OpenRouter or paid models. A model stays pinned across a floor tour.</p>${error?`<p class="lab-warning">${esc(error)}</p>`:''}<button id="models-refresh" class="button subtle">Refresh availability and pricing</button><div class="lab-models">${models.map(m=>`<article class="lab-card"><h3>${esc(m.name)}</h3><p>${esc(m.id)}</p><p>${m.free?'Current catalogue: zero price, image editing supported':esc(m.reason)}</p><p>Room images: <b>${m.roomApproved?'Quality approved':'Needs real-output review'}</b><br>360°: <b>${!m.panorama?'Capability unavailable':m.panoramaApproved?'Quality approved':'Needs real-output and seam review'}</b></p>${m.roomApproved?`<button data-revoke-model="${esc(m.id)}" data-task="room" class="button subtle">Remove room approval</button>`:''}${m.panoramaApproved?`<button data-revoke-model="${esc(m.id)}" data-task="panorama" class="button subtle">Remove 360° approval</button>`:''}</article>`).join('')}</div><h3>Test one curated candidate</h3><p>Configure IMAGEROUTER_API_KEY in .env first. For a normal room test, set an interior viewpoint using Explore → Walkthrough before opening this panel. A 360° test also requires an approved original and current design brief.</p><label class="field">Candidate<select id="quality-model">${models.map(m=>`<option value="${esc(m.id)}" ${m.free?'':'disabled'}>${esc(m.name)} · ${m.free?'free candidate':'unavailable'}</option>`).join('')}</select></label><label class="field">Task<select id="quality-task"><option value="room">Room image</option><option value="panorama">360° panorama</option></select></label><label class="field">Panorama room<select id="quality-room">${f.rooms.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></label><label class="field">Your quality-test brief<textarea id="quality-prompt" rows="3">Photorealistic warm contemporary interior, natural oak and plaster, realistic daylight. Preserve all walls, openings, scale and furniture.</textarea></label><button id="quality-generate" class="button" ${busy||!models.some(m=>m.free)?'disabled':''}>${busy?'Generation in progress…':'Generate one test image'}</button><p id="quality-progress"></p><h3>Review generated outputs</h3>${jobs.map(j=>`<article class="lab-card"><strong>${esc(j.model)} · ${esc(j.mode)} · ${esc(j.status)}</strong><p>${esc(j.error||'')}</p>${j.status==='completed'?`<button data-quality-view="${j.id}" class="button subtle">Inspect source and output</button>`:''}</article>`).join('')}<div id="quality-viewer"></div></div>`);$('#models-refresh').onclick=open;$('#quality-generate').onclick=generate;document.querySelectorAll('[data-revoke-model]').forEach(x=>x.onclick=async()=>{try{await api('/api/ai/model-quality',{method:'POST',body:JSON.stringify({action:'revoke',modelId:x.dataset.revokeModel,task:x.dataset.task})});await open();}catch(e){b.toast(e.message);}});document.querySelectorAll('[data-quality-view]').forEach(x=>x.onclick=()=>view(x.dataset.qualityView));}
 async function generate(){if(busy)return;const f=b.getFloor(),p=b.getProject(),mode=$('#quality-task').value,modelId=$('#quality-model').value,prompt=$('#quality-prompt').value,scene=b.getScene();if(!scene)return b.toast('3D is unavailable.');if(conversionNeedsApproval(p,f))return b.toast('Approve measurements and geometry in Plan lab before image generation.');const brief=planning(p).briefs[f.id],r=floorRecord(p,f.id);let source,roomId,camera;
 try{if(mode==='panorama'){if(!r.baseline||!brief||brief.layoutKey!==layoutKey(f))throw Error('Approve the original and current design brief before a panorama test.');roomId=$('#quality-room').value;const room=f.rooms.find(r=>r.id===roomId),position=roomStation(f,room);if(!position)throw Error('No valid room station.');scene.load(f,false);try{source=capturePanorama(scene,position,{floor:f,ceilingHeight:brief.ceilingHeight});}finally{b.render();}camera={position,yaw:0,pitch:0,fov:75};}else{if(!scene.walkCamera)throw Error('Enter Explore → Walkthrough and choose an interior viewpoint first.');source=scene.capture();const c=scene.walkCamera;camera={position:c.position.toArray(),yaw:c.rotation.y,pitch:c.rotation.x,fov:c.fov};}busy=true;render();let job=await api('/api/ai/jobs',{method:'POST',body:JSON.stringify({provider:'imagerouter',modelId,projectId:p.id,floorId:f.id,mode,prompt,source,camera,roomId,layoutRevision:layoutKey(f),briefFingerprint:brief?fingerprint(brief):'room-test',sceneFingerprint:sceneFingerprint(p,f)})});jobs.unshift(job);while(['queued','running'].includes(job.status)){await new Promise(r=>setTimeout(r,1500));job=await api('/api/ai/jobs/'+job.id);jobs=jobs.map(j=>j.id===job.id?job:j);if($('#quality-progress'))$('#quality-progress').textContent=job.status;}if(job.status!=='completed')throw Error(job.error||'Test generation failed.');}catch(e){b.toast(e.message);}finally{busy=false;if(visible&&$('#quality-progress'))render();}}
 function view(id){dispose?.();dispose=null;const job=jobs.find(j=>j.id===id),el=$('#quality-viewer'),checks=['layout','materials','lighting','realism',...(job.mode==='panorama'?['seams']:[])];el.innerHTML=`<h3>Inspect ${esc(job.model)}</h3><p>Compare geometry, openings, furniture, material detail and lighting. For panoramas, drag to inspect the full room and the joining seam. Reject the candidate if any criterion fails.</p><div class="quality-compare"><figure><img src="/api/ai/jobs/${id}/source" alt="Actual model capture"><figcaption>Actual model capture</figcaption></figure><figure><img src="/api/ai/jobs/${id}/result" alt="Real provider output"><figcaption>Provider-generated output</figcaption></figure></div>${job.mode==='panorama'?'<div class="panorama-stage"><canvas id="quality-sphere"></canvas></div>':''}${checks.map(k=>`<label class="lab-lock"><input data-quality-check="${k}" type="checkbox"> ${esc({layout:'Geometry, openings and furnishings preserved',materials:'Materials look convincing',lighting:'Lighting and shadows are coherent',realism:'Interior quality is acceptable',seams:'Full 360° projection and joining seam are acceptable'}[k])}</label>`).join('')}<p><button id="quality-approve" class="button">Approve this model for ${job.mode==='panorama'?'360°':'room images'} in Auto Free</button></p><p>Approval is local to this PC and task. It does not approve this room as a floor-tour pilot.</p>`;if(job.mode==='panorama')dispose=sphericalViewer($('#quality-sphere'),'/api/ai/jobs/'+id+'/result');$('#quality-approve').onclick=async()=>{try{const values=Object.fromEntries([...document.querySelectorAll('[data-quality-check]')].map(x=>[x.dataset.qualityCheck,x.checked]));await api('/api/ai/model-quality',{method:'POST',body:JSON.stringify({jobId:id,checks:values})});b.toast('Model qualified for this task. Auto Free will recheck pricing and availability each time.');await open();}catch(e){b.toast(e.message);}};el.scrollIntoView({block:'nearest'});}
 return {open};
}
